"""Operator-owned capabilities and verifiable goals, never generated by the model.

This is a controlled-fixture capability format, not a production-site adapter or
permission prompt. The caller must already have authorization for every grant.
"""
from __future__ import annotations
import json
import re
from urllib.parse import urlsplit
from .common import ValidationError, loopback_origin

ID = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,79}\Z")
KINDS = {"navigate", "click", "fill", "select", "reload", "observe"}


def require(condition, message):
    if not condition:
        raise ValidationError(message)


def object_fields(value, required, optional=()):
    require(type(value) is dict and set(required) <= set(value) <= set(required) | set(optional),
            "Missing or unexpected capability fields")


def identifier(value):
    require(type(value) is str and ID.fullmatch(value), "Invalid capability identifier")


def request_path(value):
    require(type(value) is str and 1 <= len(value) <= 300, "Invalid request target")
    p = urlsplit(value)
    require(re.fullmatch(r'/[A-Za-z0-9/_~.?=&:+,@!$()*;\-]*', value), 'Request target must use canonical ASCII URL characters')
    require(value.startswith('/') and not value.startswith('//') and not p.scheme and not p.netloc
            and not p.fragment and all(33 <= ord(c) <= 126 for c in value) and not any(c in value for c in ('%', '\\', '#', '\r', '\n', '\t', ' '))
            and all(part not in {'.', '..'} for part in p.path.split('/')), "Request target must be an exact local path")
    require(p.path + ('?' + p.query if p.query else '') == value, "Noncanonical request target")


def validate_authorization(auth):
    object_fields(auth, {"schema_version", "bug_sha256", "origin", "get_paths", "acknowledge_mutations", "actions", "probes", "checkpoints"}, {"budgets"})
    require(type(auth['schema_version']) is int and auth['schema_version'] == 1, "Unsupported capability version")
    require(type(auth['bug_sha256']) is str and re.fullmatch(r'[0-9a-f]{64}', auth['bug_sha256']), 'Missing exact bug-report binding')
    require(auth['origin'] == loopback_origin(auth['origin']), "Origin must be canonical and exact")
    require(urlsplit(auth['origin']).port not in {0, 80}, 'Use a nonzero, explicit non-default fixture port')
    # Numerical loopback avoids localhost DNS resolution ambiguity in this new adapter.
    require(urlsplit(auth['origin']).hostname in {'127.0.0.1', '::1'}, "Use an explicit numerical loopback address")
    require(type(auth['acknowledge_mutations']) is bool, "Mutation acknowledgment must be boolean")
    paths = auth['get_paths']
    require(type(paths) is list and 1 <= len(paths) <= 20 and len(set(paths)) == len(paths), "Invalid read grants")
    for path in paths:
        request_path(path)
    probes = auth['probes']
    require(type(probes) is dict and 1 <= len(probes) <= 20, "Invalid probes")
    for key, probe in probes.items():
        identifier(key)
        object_fields(probe, {'test_id', 'kind'})
        identifier(probe['test_id'])
        require(probe['kind'] in {'text', 'value', 'count'}, "Unsupported probe kind")
    actions = auth['actions']
    require(type(actions) is dict and 1 <= len(actions) <= 20, "Invalid actions")
    for key, action in actions.items():
        identifier(key)
        require(key not in {'finish', 'stop'}, "Reserved action ID")
        object_fields(action, {'kind', 'description'}, {'test_id', 'value', 'path', 'request', 'wait_for', 'max_uses'})
        kind = action['kind']
        require(kind in KINDS, "Unsupported action kind")
        require(type(action['description']) is str and 1 <= len(action['description']) <= 400, "Invalid action description")
        require(('test_id' in action) == (kind in {'click', 'fill', 'select'}), "Selector does not match action kind")
        require(('value' in action) == (kind in {'fill', 'select'}), "Value does not match action kind")
        require(('path' in action) == (kind == 'navigate'), "Path does not match action kind")
        if 'test_id' in action:
            identifier(action['test_id'])
        if 'value' in action:
            require(type(action['value']) is str and len(action['value']) <= 300, "Invalid fixed input value")
        if 'path' in action:
            request_path(action['path'])
            require(action['path'] in paths, "Navigation lacks exact read grant")
        uses = action.get('max_uses', 1 if 'request' in action else 2)
        require(type(uses) is int and 1 <= uses <= 5, "Invalid action use budget")
        if 'request' in action:
            require(kind == 'click' and auth['acknowledge_mutations'] is True and uses == 1,
                    "Mutations require explicit acknowledgment, a click and one-shot use")
            req = action['request']
            object_fields(req, {'method', 'path', 'json'})
            require(req['method'] in {'POST', 'PUT', 'PATCH'}, "Unsupported mutation method")
            request_path(req['path'])
            require(type(req['json']) is dict and len(json.dumps(req['json'], allow_nan=False)) <= 1024,
                    "Mutation body must be a bounded JSON object")
        if 'wait_for' in action:
            object_fields(action['wait_for'], {'probe', 'equals'})
            require(action['wait_for']['probe'] in probes, "Unknown wait probe")
            validate_value(action['wait_for']['equals'], probes[action['wait_for']['probe']]['kind'])
    checkpoints = auth['checkpoints']
    require(type(checkpoints) is list and 1 <= len(checkpoints) <= 8, "Invalid checkpoints")
    seen = set()
    requirement_count = 0
    for checkpoint in checkpoints:
        object_fields(checkpoint, {'id', 'after_action', 'checks'})
        identifier(checkpoint['id'])
        require(checkpoint['id'] not in seen and checkpoint['after_action'] in actions, "Invalid checkpoint identity or action")
        seen.add(checkpoint['id'])
        checks = checkpoint['checks']
        require(type(checks) is list and 1 <= len(checks) <= 8, "Invalid checkpoint checks")
        for check in checks:
            object_fields(check, {'probe', 'op', 'value', 'role'})
            require(check['probe'] in probes and check['op'] in {'equals', 'not_equals', 'contains'}
                    and check['role'] in {'precondition', 'requirement'}, "Invalid check")
            validate_value(check['value'], probes[check['probe']]['kind'])
            require(check['op'] != 'contains' or type(check['value']) is str, "contains requires text")
            requirement_count += check['role'] == 'requirement'
    require(requirement_count > 0, "At least one objective requirement is required")
    budgets = auth.get('budgets', {})
    object_fields(budgets, set(), {'max_steps', 'max_seconds'})
    require(type(budgets.get('max_steps', 12)) is int and 1 <= budgets.get('max_steps', 12) <= 30, "Invalid step budget")
    require(type(budgets.get('max_seconds', 180)) is int and 5 <= budgets.get('max_seconds', 180) <= 600, "Invalid time budget")
    require(len(json.dumps(auth, allow_nan=False)) <= 32000, "Capability document too large")
    return auth


def validate_value(value, kind):
    if kind == 'count':
        require(type(value) is int and 0 <= value <= 100, "Count must be a bounded integer")
    else:
        require(type(value) is str and len(value) <= 4000, "Probe value must be bounded text")


def decision_schema(action_ids, evidence_ids, *, completion_ready=False):
    """Expose claims only after the host has captured every required checkpoint.

    Action turns cannot express a verdict or cite evidence. Stopping in that
    phase leaves the host's inconclusive result unchanged. Assessment turns
    cannot invoke more browser actions. This narrows output choices without
    repairing or discarding any generated fields. Assessment evidence_ids must
    contain exactly the host-captured checkpoint IDs, including on abstention.
    """
    evidence_ids = list(evidence_ids) if completion_ready else []
    # Ollama rejects enum:[] even under maxItems:0. The length constraint still
    # permits exactly [] during action selection and forbids every citation.
    evidence_item = {'type': 'string'}
    if evidence_ids:
        evidence_item['enum'] = evidence_ids
    return {'type': 'object', 'additionalProperties': False,
            'required': ['action_id', 'reason', 'verdict', 'evidence_ids'],
            'properties': {
                'action_id': {'type': 'string', 'enum': ['finish', 'stop'] if completion_ready else list(action_ids) + ['stop']},
                'reason': {'type': 'string', 'minLength': 1, 'maxLength': 1000},
                'verdict': ({'type': 'string', 'enum': ['confirmed', 'not_reproduced', 'inconclusive']}
                            if completion_ready else {'type': 'null'}),
                'evidence_ids': {'type': 'array', 'minItems': len(evidence_ids), 'maxItems': len(evidence_ids), 'uniqueItems': True,
                                 'items': evidence_item}}}
